const raw = $input.first().json;
const body = raw.body || raw;
const data = body.data || body;
const analysis = data.analysis || body.analysis || {};
const dcRaw = analysis.data_collection_results || data.data_collection || body.data_collection || {};
function dcVal(key) {
  const o = dcRaw[key];
  if (o && typeof o === 'object' && 'value' in o) return o.value;
  return dcRaw[key] ?? '';
}
let transcript = data.transcript || body.transcript || '';
if (Array.isArray(transcript)) {
  transcript = transcript.map(t => {
    if (typeof t === 'string') return t;
    return (t.role || '') + ': ' + (t.message || t.content || '');
  }).join('\n');
}
const dyn = (data.conversation_initiation_client_data || {}).dynamic_variables || {};
const leadId = String(dyn.lead_id_odoo || dcVal('lead_id_odoo') || body.lead_id_odoo || body.lead_id || '').replace(/\D/g, '') || '';
return [{
  json: {
    conversation_id: data.conversation_id || body.conversation_id || body.call_id || '',
    lead_id: leadId,
    transcript,
    call_duration_seconds: data.metadata?.call_duration_secs || data.call_duration_seconds || body.duration || 0,
    call_successful: (data.status || body.status) !== 'failed',
    data_collection: dcRaw,
    lead_name: dyn.lead_name || dcVal('lead_name') || '',
    project_type: dyn.project_type || dcVal('project_type') || 'multi',
    city: dyn.city || dcVal('city') || '',
    budget_range: dyn.budget_range || dcVal('budget_range') || '',
    property_type: dyn.property_type || dcVal('property_type') || '',
    phone: dyn.phone || dcVal('phone') || ''
  }
}];

const p = $('Parser payload EL').first().json;
const apiKey = '{{ANTHROPIC_API_KEY}}';
const prompt = `Tu es expert qualification leads rénovation résidentielle Québec (SoumissionEntrepreneurs). Analyse et retourne UNIQUEMENT un JSON valide sans markdown.\n\nLead:\n- Nom: ${p.lead_name}\n- Ville: ${p.city}\n- Projet: ${p.project_type}\n- Budget: ${p.budget_range}\n- Type propriété: ${p.property_type}\n- Durée appel: ${p.call_duration_seconds}s\n- Transcript (extrait): ${(p.transcript || '').slice(0, 2000)}\n\nHOT: budget > 25k, délai < 3 mois, veut visite/soumissions.\nWARM: projet défini, timing flexible.\nCOLD: magasinage, pas de budget, délai > 1 an.\n\nRéponds: {"score":"hot|warm|cold","score_numeric":0-100,"transfer_now":true|false,"plans_3d_recommanded":true|false,"subventions_applicables":["renoclimat"],"subvention_estimee":0,"upload_link_sent":true,"summary":"2 phrases","next_action":"...","odoo_stage":"Qualifié|En développement|Nouveau"}`;
let parsed = { score: 'warm', score_numeric: 50, transfer_now: false, summary: '', next_action: '', odoo_stage: 'En développement', subventions_applicables: [], subvention_estimee: 0, upload_link_sent: true };
if (!apiKey || apiKey.startsWith('{{')) {
  const dur = parseInt(p.call_duration_seconds || 0, 10);
  if (dur < 15) parsed = { ...parsed, score: 'cold', score_numeric: 20, odoo_stage: 'Nouveau' };
  return [{ json: { ...p, ...parsed } }];
}
try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
    body: { model: 'claude-sonnet-4-20250514', max_tokens: 500, messages: [{ role: 'user', content: prompt }] },
    json: true,
  });
  let text = (res.content && res.content[0] && res.content[0].text) || '';
  const match = text.match(/\{[\s\S]*\}/);
  if (match) parsed = { ...parsed, ...JSON.parse(match[0]) };
} catch (e) {
  parsed.summary = 'Scoring fallback: ' + String(e.message || e);
}
return [{ json: { ...p, ...parsed } }];

const j = $input.first().json;
const token = '{{HAIDLY_WEBHOOK_TOKEN}}';
const body = {
  lead_id: parseInt(j.lead_id, 10),
  score: j.score,
  score_numeric: j.score_numeric,
  transfer_now: true,
  summary: j.summary,
  next_action: j.next_action,
  odoo_stage: j.odoo_stage || 'Qualifié',
  conversation_id: j.conversation_id,
  transcript: j.transcript,
  subventions_applicables: Array.isArray(j.subventions_applicables) ? j.subventions_applicables.join(',') : (j.subventions_applicables || ''),
  subvention_estimee: j.subvention_estimee || 0,
  upload_link_sent: true,
  increment_call_attempt: true,
  nurture_active: false
};
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://intellixcrm.com/api/haidly/lead/update',
  headers: { 'X-Haidly-Webhook-Token': token, 'Content-Type': 'application/json' },
  body,
  json: true,
});
return [{ json: { ...j, odoo: res } }];

const j = $input.first().json;
const token = '{{HAIDLY_WEBHOOK_TOKEN}}';
const body = {
  lead_id: parseInt(j.lead_id, 10),
  score: j.score,
  score_numeric: j.score_numeric,
  transfer_now: false,
  summary: j.summary,
  next_action: j.next_action,
  odoo_stage: j.odoo_stage || 'En développement',
  conversation_id: j.conversation_id,
  transcript: j.transcript,
  subventions_applicables: Array.isArray(j.subventions_applicables) ? j.subventions_applicables.join(',') : (j.subventions_applicables || ''),
  subvention_estimee: j.subvention_estimee || 0,
  upload_link_sent: true,
  increment_call_attempt: true,
  nurture_active: true
};
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://intellixcrm.com/api/haidly/lead/update',
  headers: { 'X-Haidly-Webhook-Token': token, 'Content-Type': 'application/json' },
  body,
  json: true,
});
return [{ json: { ...j, odoo: res } }];

const j = $('Claude Scoring').first().json;
const phone = j.phone || '';
if (!phone || j.score !== 'hot') return [{ json: j }];
const sid = '{{TWILIO_ACCOUNT_SID}}';
const auth = Buffer.from(sid + ':{{TWILIO_AUTH_TOKEN}}').toString('base64');
const first = (j.lead_name || '').split(' ')[0] || 'Bonjour';
await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.twilio.com/2010-04-01/Accounts/${sid}/Messages.json`,
  headers: { Authorization: 'Basic ' + auth, 'Content-Type': 'application/x-www-form-urlencoded' },
  body: `To=${encodeURIComponent(phone)}&From=${encodeURIComponent('+15817058118')}&Body=${encodeURIComponent(first + ', votre projet de rénovation nous enthousiasme! Un conseiller SoumissionEntrepreneurs vous contacte sous peu. Sans frais, sans obligation.')}`,
});
return [{ json: j }];

const j = $('Claude Scoring').first().json;
const phone = j.phone || '';
if (!phone) return [{ json: j }];
const sid = '{{TWILIO_ACCOUNT_SID}}';
const auth = Buffer.from(sid + ':{{TWILIO_AUTH_TOKEN}}').toString('base64');
const first = (j.lead_name || '').split(' ')[0] || 'Bonjour';
const emoji = { cuisine: '🍳', salle_de_bain: '🛁', sous_sol: '🏠', patio: '☀️' }[j.project_type] || '🏠';
await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.twilio.com/2010-04-01/Accounts/${sid}/Messages.json`,
  headers: { Authorization: 'Basic ' + auth, 'Content-Type': 'application/x-www-form-urlencoded' },
  body: `To=${encodeURIComponent(phone)}&From=${encodeURIComponent('+15817058118')}&Body=${encodeURIComponent(first + '! ' + emoji + ' Haidly de SoumissionEntrepreneurs — envoyez vos photos ici: https://soumissionentrepreneurs.com/ — Plans 3D GRATUITS avec nos entrepreneurs RBQ. Sans frais!')}`,
});
return [{ json: { ...j, upload_link_sent: true } }];

const j = $('Claude Scoring').first().json;
if (j.score === 'hot' || !j.lead_id) return [];
const token = '{{HAIDLY_WEBHOOK_TOKEN}}';
let lead = {};
try {
  lead = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://intellixcrm.com/api/haidly/lead/${j.lead_id}`,
    headers: { 'X-Haidly-Webhook-Token': token },
    json: true,
  });
} catch (e) {}
const dur = parseInt(j.call_duration_seconds || 0, 10);
return [{ json: {
  lead_id: j.lead_id,
  phone: lead.phone || j.phone,
  first_name: lead.first_name || j.lead_name,
  project_type: lead.project_type || j.project_type,
  city: lead.city || j.city,
  score: j.score,
  call_answered: dur >= 25 && j.call_successful !== false,
  call_duration_seconds: dur,
  total_call_attempts: (lead.haidly_total_call_attempts || 0) + 1,
  skip_initial_call: true
}}];
